import { useState } from 'react';
import {
  JxButton,
  JxInput,
  JxLabel,
  JxCard,
  JxStack,
  JxText,
  JxBadge,
  JxDivider,
} from '@jinx-ui/react';

type StepId = 'contacts' | 'address' | 'review';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  street: string;
  city: string;
  postalCode: string;
}

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS: { id: StepId; label: string }[] = [
  { id: 'contacts', label: 'Контакты' },
  { id: 'address', label: 'Адрес' },
  { id: 'review', label: 'Проверка' },
];

const INITIAL_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  street: '',
  city: '',
  postalCode: '',
};

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [data, setData] = useState<RegistrationData>(INITIAL_DATA);

  const currentStep = STEPS[stepIndex];
  const isFirstStep = stepIndex === 0;
  const isLastStep = stepIndex === STEPS.length - 1;

  const updateField = (field: keyof RegistrationData) => (value: string) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const handleBack = () => {
    setStepIndex((i) => Math.max(0, i - 1));
  };

  const handleNext = () => {
    if (isLastStep) {
      onSubmit(data);
      return;
    }
    setStepIndex((i) => Math.min(STEPS.length - 1, i + 1));
  };

  return (
    <JxCard className="jx-p-lg jx-w-full">
      <JxStack direction="row" gap="sm" align="center" className="jx-mb-lg">
        {STEPS.map((step, index) => (
          <JxStack key={step.id} direction="row" gap="sm" align="center">
            <JxBadge
              variant={
                index === stepIndex ? 'primary' : index < stepIndex ? 'success' : 'neutral'
              }
            >
              {index + 1}
            </JxBadge>
            <JxText size="sm" weight={index === stepIndex ? 'bold' : 'regular'}>
              {step.label}
            </JxText>
            {index < STEPS.length - 1 && <JxDivider orientation="horizontal" className="jx-flex-1" />}
          </JxStack>
        ))}
      </JxStack>

      {currentStep.id === 'contacts' && (
        <JxStack direction="column" gap="md">
          <JxStack direction="column" gap="xs">
            <JxLabel htmlFor="fullName">Имя и фамилия</JxLabel>
            <JxInput
              id="fullName"
              value={data.fullName}
              onValueChange={updateField('fullName')}
              placeholder="Иван Иванов"
            />
          </JxStack>
          <JxStack direction="column" gap="xs">
            <JxLabel htmlFor="email">Email</JxLabel>
            <JxInput
              id="email"
              type="email"
              value={data.email}
              onValueChange={updateField('email')}
              placeholder="ivan@example.com"
            />
          </JxStack>
          <JxStack direction="column" gap="xs">
            <JxLabel htmlFor="phone">Телефон</JxLabel>
            <JxInput
              id="phone"
              type="tel"
              value={data.phone}
              onValueChange={updateField('phone')}
              placeholder="+7 900 000-00-00"
            />
          </JxStack>
        </JxStack>
      )}

      {currentStep.id === 'address' && (
        <JxStack direction="column" gap="md">
          <JxStack direction="column" gap="xs">
            <JxLabel htmlFor="street">Улица и дом</JxLabel>
            <JxInput
              id="street"
              value={data.street}
              onValueChange={updateField('street')}
              placeholder="ул. Ленина, 10"
            />
          </JxStack>
          <JxStack direction="column" gap="xs">
            <JxLabel htmlFor="city">Город</JxLabel>
            <JxInput
              id="city"
              value={data.city}
              onValueChange={updateField('city')}
              placeholder="Москва"
            />
          </JxStack>
          <JxStack direction="column" gap="xs">
            <JxLabel htmlFor="postalCode">Индекс</JxLabel>
            <JxInput
              id="postalCode"
              value={data.postalCode}
              onValueChange={updateField('postalCode')}
              placeholder="123456"
            />
          </JxStack>
        </JxStack>
      )}

      {currentStep.id === 'review' && (
        <JxStack direction="column" gap="sm">
          <JxText weight="bold">Проверьте данные перед отправкой</JxText>
          <JxStack direction="column" gap="xs">
            <JxText size="sm">Имя: {data.fullName || '—'}</JxText>
            <JxText size="sm">Email: {data.email || '—'}</JxText>
            <JxText size="sm">Телефон: {data.phone || '—'}</JxText>
            <JxText size="sm">Адрес: {data.street || '—'}</JxText>
            <JxText size="sm">Город: {data.city || '—'}</JxText>
            <JxText size="sm">Индекс: {data.postalCode || '—'}</JxText>
          </JxStack>
        </JxStack>
      )}

      <JxStack direction="row" justify="between" className="jx-mt-lg">
        <JxButton variant="secondary" onClick={handleBack} disabled={isFirstStep}>
          Назад
        </JxButton>
        <JxButton variant="primary" onClick={handleNext}>
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </JxStack>
    </JxCard>
  );
}

